// Expansão autoral: diálogos próprios e seis focos gramaticais por nível.
const expansionFree=[], expansionPremium=[];
const expansionLevels=['Basic','Pre-Intermediate','Intermediate','Upper','Advanced'];
const expansionFocus=[
 ['Be e possessivos','Use my/your antes de um substantivo; be liga o sujeito à descrição.'],
 ['There is/are','There is apresenta um item; there are apresenta itens no plural.'],
 ['Can e habilidade','Depois de can, use o verbo básico, sem to ou s.'],
 ['Presente simples','He/she/it normalmente recebe s no presente afirmativo; a pergunta usa does + verbo básico.'],
 ['A/an e substantivos contáveis','A e an acompanham um substantivo singular contável; a escolha depende do som inicial.'],
 ['Imperativos negativos','Don’t + verbo básico pede que alguém evite uma ação.'],
 ['Passado simples','Um tempo concluído, como yesterday, pede passado simples; depois de did, use o verbo básico.'],
 ['Comparativos','Comparativos curtos costumam usar er; adjetivos longos usam more. Than liga os itens comparados.'],
 ['Presente contínuo','Be + verbo com ing descreve uma ação em andamento; use a forma de be que combina com o sujeito.'],
 ['Going to para planos','Be + going to + verbo básico apresenta um plano ou uma intenção.'],
 ['Conselhos com should','Should + verbo básico faz uma recomendação; shouldn’t recomenda evitar uma ação.'],
 ['Much/many e quantidade','Many acompanha plural contável; much acompanha nomes não contáveis, como water.'],
 ['Present perfect e yet','Have/has + particípio liga o passado ao presente; yet ocorre frequentemente em perguntas e negativas.'],
 ['First conditional','If + presente apresenta uma condição futura; o resultado usa will + verbo básico.'],
 ['Second conditional','If + passado e would + verbo básico apresenta uma hipótese imaginada.'],
 ['Orações relativas','Who identifica pessoas; that/which pode identificar coisas. A informação completa o nome.'],
 ['Used to','Used to + verbo básico descreve um hábito ou estado passado que mudou.'],
 ['Gerúndio depois de enjoy','Depois de enjoy, use a forma com ing. A escolha da forma depende do verbo que vem antes.'],
 ['Passiva','Be + particípio coloca em foco quem ou o que recebe a ação; by pode indicar quem agiu.'],
 ['Discurso indireto','No relato solicitado com recuo temporal, am/is vira was e can vira could; preserve condições e sentido.'],
 ['Third conditional','If + had + particípio e would have + particípio imagina um passado diferente do que ocorreu.'],
 ['Dedução com might/must','Might indica possibilidade; must indica uma dedução forte. Depois do modal, use verbo básico.'],
 ['Both e neither','Both apresenta dois itens juntos; neither indica nenhum dos dois. Neither + nome singular usa verbo singular nestes exemplos.'],
 ['Although e despite','Although introduz oração; despite acompanha nome ou forma com ing. Não junte although e but para as mesmas duas ideias.'],
 ['Inversão com not only','Ao iniciar com Not only, use auxiliar antes do sujeito; depois de does, o verbo fica na forma básica.'],
 ['Frases clivadas','It was… that… destaca uma informação específica sem mudar o acontecimento.'],
 ['Mixed conditional','If + had + particípio pode ter resultado atual com would + verbo básico: uma causa passada afeta o presente.'],
 ['Orações reduzidas com particípio','Uma oração inicial com particípio precisa ter o mesmo agente do sujeito da oração principal. Evite agente ambíguo.'],
 ['Wish e situações atuais','Wish + passado expressa desejo de que a situação atual fosse diferente; had pode referir-se à posse atual.'],
 ['Linguagem de cautela','May/might + verbo básico delimita a certeza. Uma amostra pequena sugere, mas não prova automaticamente uma conclusão geral.']
];
function expansionAdd(premium,li,theme,t,v,dialog,translation,s,bad,missing,q,goal,writing){
 const index=(premium?expansionPremium:expansionFree).length,id=`extra-${premium?'premium':'free'}${String(index+1).padStart(2,'0')}`,focus=expansionFocus[li*6+index%6];
 const d=dialog.split('|').map((x,j)=>`${j%2?'Leo':'Maya'}: ${x}`),tr=translation.split('|'),vocab=v.split('|').map(x=>{const[en,pt]=x.split('=');return{en,pt}});
 const exercises=[{type:'gap',prompt:s.replace(missing,'___')+` (Use a estrutura da aula.)`,accepted:[missing],explanation:`No modelo, a forma adequada é ${missing}. ${focus[1]}`},{type:'choice',prompt:'Qual frase expressa a estrutura estudada corretamente?',options:[s,bad],answer:0,explanation:focus[1]},{type:'rewrite',prompt:`Corrija a estrutura e reescreva a frase inteira: ${bad}`,accepted:[s],explanation:`Compare sujeito, auxiliar e verbo com o modelo: ${s}`}];
 const lesson={id,premium,theme,module:0,level:expansionLevels[li],cefr:['A1','A2','B1','B2','C1'][li],t,o:writing,g:focus[1],v:vocab,d,tr,s,grammarTopic:focus[0],grammarExercises:exercises,q:[{prompt:q[0],options:q.slice(1,4),answer:0,explanation:q[4],type:'reading'},{prompt:'Qual é o objetivo principal da conversa?',options:[goal,'To agree without discussing any details','To end the activity without finding a solution'],answer:0,explanation:'Observe o problema, as propostas e o próximo passo do diálogo.',type:'reading'},{prompt:'Escolha a frase com a estrutura adequada.',options:[s,bad,s.replace(/\.$/,'')+' yesterday tomorrow.'],answer:0,explanation:focus[1],type:'language'},{prompt:`Qual é o sentido de “${vocab[4].en}” nesta aula?`,options:[vocab[4].pt,vocab[1].pt,vocab[6].pt],answer:0,explanation:`Neste contexto, ${vocab[4].en} significa ${vocab[4].pt}.`,type:'language'}],w:`${writing} Escreva ${['3–5 frases','40–60 palavras','70–100 palavras','110–140 palavras','160–200 palavras'][li]}, usando a estrutura da aula e personagens fictícios.`,model:d.map(x=>x.replace(/^[^:]+: /,'')).join(' '),k:'Desenhe a situação, selecione três palavras úteis e escreva com apoio dos exemplos.',teen:'Adapte a situação para um clube fictício e justifique as escolhas para outro participante.',tip:li<2?'Ouça uma fala por vez e repita. A transcrição e a tradução estão disponíveis como apoio.':'Observe como a gramática muda o sentido. Pratique pausas, contrastes e grau de certeza.'};
 (premium?expansionPremium:expansionFree).push(lesson);
}
// BASIC — be/possessivos, existência, habilidade, rotina, artigos, imperativos.
expansionAdd(false,0,'school','Whose notebook is this?','notebook=caderno|name=nome|desk=carteira|blue=azul|owner=dono|class=turma|mine=meu|your=seu','This blue notebook is on my desk. Is it your notebook?|No, my notebook is green. There is a name on the cover.|It says Ana. Is Ana in our class?|Yes, she is. Let’s give it to her after the lesson.','Este caderno azul está na minha carteira. É seu caderno?|Não, meu caderno é verde. Há um nome na capa.|Está escrito Ana. A Ana é da nossa turma?|Sim. Vamos entregar a ela depois da aula.','My notebook is green.','My notebook am green.','is',['De quem é o caderno azul?','Ana','Leo','The teacher','O nome Ana aparece na capa.'],'To return a notebook to its owner','Identificar um objeto e seu dono com possessivos e be.');
expansionAdd(false,0,'science','Our seed tray','seed=semente|tray=bandeja|soil=terra|water=água|leaf=folha|light=luz|two=dois|window=janela','There are two leaves in our tray!|And there is a tiny stem. The soil is dry.|Let’s add a little water. Is the tray near the window?|Yes. We can draw the plant today and compare it tomorrow.','Há duas folhas na nossa bandeja!|E há um caule bem pequeno. A terra está seca.|Vamos pôr um pouco de água. A bandeja fica perto da janela?|Sim. Podemos desenhar a planta hoje e comparar amanhã.','There are two leaves.','There is two leaves.','are',['O que eles vão comparar?','Drawings of the plant','Two phones','Their shoes','Eles vão desenhar a planta e compará-la no dia seguinte.'],'To observe a growing plant','Descrever o que existe em uma experiência com plantas.');
expansionAdd(false,0,'nature','A quiet bird watch','bird=pássaro|nest=ninho|tree=árvore|quiet=quieto|wing=asa|watch=observar|move=mover|binoculars=binóculos','Can you see the bird in that tree?|Yes, I can. It has a red wing. Can I move closer?|Let’s stay here. We can watch with binoculars.|Good idea. We can draw it without touching the nest.','Você consegue ver o pássaro naquela árvore?|Sim. Ele tem uma asa vermelha. Posso chegar mais perto?|Vamos ficar aqui. Podemos observar com binóculos.|Boa ideia. Podemos desenhá-lo sem tocar no ninho.','We can watch the bird.','We can watches the bird.','watch',['Como eles vão observar o pássaro?','With binoculars','By touching the nest','By catching it','O diálogo propõe observar à distância com binóculos.'],'To observe a bird without disturbing it','Expressar habilidades e possibilidades ao observar a natureza.');
expansionAdd(false,0,'citizenship','Our shared table','table=mesa|share=compartilhar|help=ajudar|clean=limpar|turn=vez|club=clube|every=cada|Friday=sexta-feira','Our club meets every Friday. Who cleans the table?|Ravi cleans it this week. I put the pencils away.|Does everyone have a turn?|Yes. We change jobs each week, so the work is shared.','Nosso clube se reúne toda sexta-feira. Quem limpa a mesa?|O Ravi limpa esta semana. Eu guardo os lápis.|Todos têm uma vez?|Sim. Trocamos as tarefas a cada semana, para dividir o trabalho.','Ravi cleans the table.','Ravi clean the table.','cleans',['Com que frequência eles trocam as tarefas?','Each week','Each hour','Never','As tarefas mudam a cada semana.'],'To share regular club tasks','Descrever uma rotina e dividir tarefas usando presente simples.');
expansionAdd(false,0,'food','A snack for the trip','apple=maçã|banana=banana|box=caixa|snack=lanche|orange=laranja|bottle=garrafa|bring=trazer|choose=escolher','I have an apple and a bottle of water.|I have a banana. Do we need a big box?|No. A small box is fine. Ana has an orange.|Let’s ask the teacher where to put our snacks.','Tenho uma maçã e uma garrafa de água.|Tenho uma banana. Precisamos de uma caixa grande?|Não. Uma caixa pequena serve. A Ana tem uma laranja.|Vamos perguntar à professora onde guardar nossos lanches.','Ana has an orange.','Ana has a orange.','an',['O que Ana tem?','An orange','A sandwich','A pear','A terceira fala informa que Ana tem uma laranja.'],'To organize snacks for a school trip','Nomear itens contáveis de um lanche com a e an.');
expansionAdd(false,0,'esports','Pause and take turns','pause=pausar|screen=tela|turn=vez|team=equipe|shout=gritar|rest=descansar|rule=regra|fair=justo','It is my turn, but the screen is hard to see.|Let’s pause. Don’t shout at your teammate.|Okay. We can move the chair and take turns.|And let’s rest after this round. That is our club rule.','É minha vez, mas é difícil enxergar a tela.|Vamos pausar. Não grite com seu colega de equipe.|Tudo bem. Podemos mudar a cadeira de lugar e alternar as vezes.|E vamos descansar depois desta rodada. Essa é a regra do clube.','Don’t shout at your teammate.','Don’t shouts at your teammate.','shout',['O que acontecerá após esta rodada?','A rest','Another hour without a break','A prize sale','O grupo combina uma pausa para descanso.'],'To agree on respectful game rules','Estabelecer regras respeitosas usando imperativos negativos.');
expansionAdd(true,0,'cinema','A costume with a name','costume=figurino|hat=chapéu|label=etiqueta|actor=ator|scarf=cachecol|box=caixa|red=vermelho|stage=palco','Is this your red scarf for the film?|No, my scarf is yellow. That one is Sofia’s.|There is a label in the costume box. It says Sofia.|Then let’s put the scarf with her hat. She is our first actor today.','Este cachecol vermelho é seu para o filme?|Não, meu cachecol é amarelo. Esse é da Sofia.|Há uma etiqueta na caixa de figurinos. Está escrito Sofia.|Então vamos deixar o cachecol com o chapéu dela. Ela é nossa primeira atriz hoje.','My scarf is yellow.','My scarf are yellow.','is',['De quem é o cachecol vermelho?','Sofia','Maya','The director','A etiqueta identifica Sofia como dona.'],'To return part of a costume','Identificar figurinos e seus donos com possessivos.');
expansionAdd(true,0,'comics','Four panels, one page','panel=quadro|page=página|bubble=balão|hero=herói|door=porta|draw=desenhar|open=abrir|empty=vazio','There are four panels on this page.|There is an empty bubble in the last panel. What can the hero say?|The door is open. Maybe: Welcome!|Yes. Let’s draw a friend in the doorway.','Há quatro quadros nesta página.|Há um balão vazio no último quadro. O que o herói pode dizer?|A porta está aberta. Talvez: Bem-vindo!|Sim. Vamos desenhar um amigo na entrada.','There are four panels.','There is four panels.','are',['Onde está o balão vazio?','In the last panel','On the cover','Behind the book','O balão está no último quadro.'],'To complete a comic page','Descrever quadros e elementos de uma página de quadrinhos.');
expansionAdd(true,0,'series','Can the robot read maps?','robot=robô|map=mapa|island=ilha|boat=barco|bridge=ponte|find=encontrar|read=ler|rescue=resgatar','Our invented series has a little robot. Can it read maps?|Yes, it can, but it can’t swim.|Then it needs a boat to reach the island.|Its friend can build one. They can rescue the lost bird together.','Nossa série inventada tem um pequeno robô. Ele sabe ler mapas?|Sim, mas não sabe nadar.|Então precisa de um barco para chegar à ilha.|Seu amigo pode construir um. Juntos, eles podem resgatar o pássaro perdido.','The robot can read maps.','The robot can reads maps.','read',['Por que o robô precisa de um barco?','It cannot swim','It cannot read','It has no friend','O robô lê mapas, mas não nada.'],'To describe a fictional character’s abilities','Descrever habilidades de um personagem original com can.');
expansionAdd(true,0,'books','A librarian’s morning','librarian=bibliotecário|shelf=prateleira|sort=organizar|morning=manhã|story=história|return=devolver|open=abrir|list=lista','What does our librarian do in the morning?|She opens the library and sorts the books.|Does she read a story to the club?|Yes. She reads one on Tuesdays, after we return our books.','O que nossa bibliotecária faz de manhã?|Ela abre a biblioteca e organiza os livros.|Ela lê uma história para o clube?|Sim. Lê uma às terças-feiras, depois que devolvemos os livros.','She sorts the books.','She sort the books.','sorts',['Quando ela lê para o clube?','On Tuesdays','Every midnight','On Sundays only','A história é lida às terças-feiras.'],'To describe a librarian’s routine','Descrever a rotina de uma biblioteca no presente simples.');
expansionAdd(true,0,'travel','An umbrella for the museum','umbrella=guarda-chuva|bag=bolsa|museum=museu|ticket=ingresso|entrance=entrada|rain=chuva|adult=adulto|coat=casaco','It is rainy. Do we need an umbrella?|Yes. I have a coat, too. Our tickets are in the bag.|Where is the museum entrance?|Let’s ask the adult with our group. We can stay together.','Está chovendo. Precisamos de um guarda-chuva?|Sim. Também tenho um casaco. Nossos ingressos estão na bolsa.|Onde fica a entrada do museu?|Vamos perguntar ao adulto que acompanha nosso grupo. Podemos ficar juntos.','We need an umbrella.','We need a umbrella.','an',['Onde estão os ingressos?','In the bag','Under the coat','At school','A segunda fala indica a bolsa.'],'To prepare for a museum visit','Preparar itens para uma visita fictícia usando artigos.');
expansionAdd(true,0,'music','Careful with the drum','drum=tambor|stick=baqueta|floor=chão|sound=som|drop=deixar cair|hold=segurar|soft=suave|practice=praticar','This is our new drum. How do I hold the sticks?|Like this. Don’t drop the drum on the floor.|Okay. Can we try a soft sound first?|Yes. Let’s practice one short rhythm together.','Este é nosso novo tambor. Como seguro as baquetas?|Assim. Não deixe o tambor cair no chão.|Tudo bem. Podemos tentar um som suave primeiro?|Sim. Vamos praticar juntos um ritmo curto.','Don’t drop the drum.','Don’t drops the drum.','drop',['Que som eles tentarão primeiro?','A soft sound','The loudest possible sound','No sound ever','Eles combinam começar com um som suave.'],'To handle an instrument carefully','Dar orientações de cuidado com imperativos.');
